html,body{margin:0;background:var(--web-bg);font-family:var(--font-body)}
a{color:var(--ink-80);text-decoration:none}a:hover{color:var(--ink)}
.h1{font-family:var(--font-display);font-weight:400;line-height:1.2;letter-spacing:0em;color:var(--ink)}
.cat{display:inline-block;font-size:12px;letter-spacing:0.01em;color:#814ADE;background:rgba(129,74,222,0.08);border-radius:999px;padding:5px 12px}
.art p{font-size:17px;line-height:1.75;color:var(--ink-body);margin:20px 0 0}
.art h2{font-family:var(--font-display);font-weight:400;font-size:28px;line-height:1.3;color:var(--ink);margin:56px 0 0}
.art h3{font-family:var(--font-body);font-weight:600;font-size:18px;line-height:1.4;color:var(--ink);margin:36px 0 0}
.art ul,.art ol{font-size:17px;line-height:1.75;color:var(--ink-body);margin:18px 0 0;padding-left:22px}
.art li{margin-top:10px;padding-left:4px}
.art li::marker{color:var(--ink-muted)}
.art a{color:#814ADE;text-decoration:underline;text-underline-offset:3px;text-decoration-thickness:1px}
.art a:hover{color:#6B3BC0}
.art strong{font-weight:600;color:var(--ink)}
.art blockquote{margin:44px 0 0;padding-left:24px;border-left:2px solid #814ADE;font-family:var(--font-display);font-weight:400;font-size:24px;line-height:1.45;color:var(--ink)}
.card{display:flex;flex-direction:column;background:#F7F5F0;border:1px solid var(--hairline);border-radius:14px;padding:14px 14px 20px;transition:border-color .15s ease-out,box-shadow .15s ease-out}
.card:hover{border-color:#814ADE66;box-shadow:0 0 0 1px #814ADE1A}
.ptitle{font-family:var(--font-display);font-weight:400;color:var(--ink);text-wrap:pretty}
.relgrid{display:grid;grid-template-columns:repeat(3,1fr);gap:24px;align-items:stretch}
@media (max-width:900px){.relgrid{grid-template-columns:1fr}}
.sc-placeholder{background:transparent!important;border-color:transparent!important;box-shadow:none!important}
.sc-placeholder::before,.sc-placeholder::after{display:none!important}

html,body{margin:0;background:var(--web-bg);font-family:var(--font-body)}
a{color:var(--ink-80);text-decoration:none}a:hover{color:var(--ink)}
.navtoggle{display:none;align-items:center;justify-content:center;width:44px;height:44px;margin-left:auto;background:none;border:0;padding:0;cursor:pointer;color:var(--ink);font-size:22px}
.navpanel{display:none}
.navbar{backdrop-filter:blur(7px);-webkit-backdrop-filter:blur(7px)}
@media (max-width:767px){.navwrap{padding:14px 16px 0}
.navbar{width:100%;gap:12px;padding:10px 10px 10px 16px}
.navlinks{display:none}
.navtoggle{display:flex}
.navpanel{position:absolute;left:16px;right:16px;top:calc(100% + 8px);z-index:30;flex-direction:column;gap:2px;background:#FDFAF4;border:1px solid #AAA69E22;border-radius:16px;padding:12px;box-shadow:0 12px 30px rgba(127,100,170,0.14)}
.navpanel.open{display:flex}
.navpanel a{display:block;padding:12px 10px;font-size:16px;min-height:44px;box-sizing:border-box}}
.btn-start{transition:background .15s ease,color .15s ease}
.btn-start:hover{background:#C6F7DA!important;color:var(--ink)!important}
.btn-start.btn-nav:hover{background:#1B1536!important;color:#fff!important}

