.sect>div:first-child{width:230px;flex:none}
.sect>div:last-child{flex:1;max-width:700px}
.meta{display:flex;flex-direction:column;gap:4px;padding:18px 0;border-top:1px solid var(--hairline)}
.meta span:first-child{font-size:12px;letter-spacing:0.03em;color:var(--ink-muted)}
.meta span:last-child{font-size:15px;color:var(--ink)}
